mapper.select:
SELECT v.id, v.policy_type, v.version, v.requires_consent, v.is_required, v.requires_reconsent, v.consent_basis_version_id, v.effective_at, v.published_at, v.is_active FROM policy_versions v WHERE v.policy_type IN
#{policyType}
AND v.is_active = 1 AND v.published_at IS NOT NULL AND v.effective_at <= #{currentTime} AND NOT EXISTS ( SELECT 1 FROM policy_versions newer WHERE newer.policy_type = v.policy_type AND newer.is_active = 1 AND newer.published_at IS NOT NULL AND newer.effective_at <= #{currentTime} AND (newer.effective_at > v.effective_at OR (newer.effective_at = v.effective_at AND newer.id > v.id)) )

SELECT id, policy_type, version, requires_consent, is_required, requires_reconsent,
       consent_basis_version_id, effective_at, published_at, is_active
FROM policy_versions WHERE id = #{id}

SELECT t.policy_version_id, t.locale, t.title, t.content FROM policy_translations t WHERE t.policy_version_id IN
#{versionId}
AND t.locale IN (#{locale}, #{fallbackLocale})
